CREATE EXTENSION IF NOT EXISTS vector; CREATE TABLE IF NOT EXISTS knowledge.document(document_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,source_type TEXT,source_id TEXT,source_name TEXT,source_uri TEXT,content_sha256 CHAR(64) UNIQUE,source_language VARCHAR(20) DEFAULT 'en',canonical_language VARCHAR(20) DEFAULT 'en',source_content TEXT,canonical_content TEXT,sw_release TEXT,primary_ecu TEXT,related_ecus TEXT[] DEFAULT '{}',dtc_codes TEXT[] DEFAULT '{}',approval_status TEXT DEFAULT 'Draft',root_cause TEXT,corrective_action TEXT,validation_result TEXT,metadata JSONB DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS knowledge.chunk(chunk_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,document_id BIGINT REFERENCES knowledge.document(document_id) ON DELETE CASCADE,chunk_index INT,chunk_text TEXT,embedding VECTOR(1024),embedding_model TEXT,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,UNIQUE(document_id,chunk_index)); CREATE TABLE IF NOT EXISTS knowledge.retrieval_audit(retrieval_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,query_id UUID,query_text TEXT,chunk_id BIGINT REFERENCES knowledge.chunk(chunk_id),rank_number INT,distance DOUBLE PRECISION,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS knowledge.ai_analysis(analysis_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,query_id UUID,report_id BIGINT REFERENCES raw.diagnostic_report(report_id),model_name TEXT,prompt_version TEXT,response_json JSONB,engineering_confirmation_required BOOLEAN DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS knowledge.engineer_feedback(feedback_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,analysis_id BIGINT REFERENCES knowledge.ai_analysis(analysis_id),decision TEXT,confirmed_root_cause TEXT,confirmed_fix TEXT,usefulness_score INT,comments TEXT,reviewed_by TEXT,reviewed_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
